const state={category:'全部',source:'全部',articles:[]};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function buttons(id,values,key){document.getElementById(id).innerHTML=values.map(v=>`<button aria-pressed="${state[key]===v}" data-key="${key}" data-value="${esc(v)}">${esc(v)}</button>`).join('')}
function card(a){return `<article><div class="meta"><span class="verified">已核验</span>　${esc(a.published_at.slice(0,10))}　${esc(a.publisher)}</div><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><details><summary>查看背景与核验依据</summary><p><b>背景：</b>${esc(a.background)}</p><p><b>影响：</b>${esc(a.impact)}</p><p><b>核验：</b>${esc(a.verification.note)}</p><a class="source" target="_blank" rel="noopener noreferrer" href="${encodeURI(a.sources[0].url)}">阅读官方原文</a></details></article>`}
function render(){const list=state.articles.filter(a=>(state.category==='全部'||a.category===state.category)&&(state.source==='全部'||a.publisher===state.source));document.getElementById('count').textContent=list.length;document.getElementById('news-grid').innerHTML=list.slice(1).map(card).join('')||'<p>当前筛选暂无资讯。</p>';const a=list[0];document.getElementById('hero').innerHTML=a?`<div class="hero-meta"><span class="verified">已核验</span>　${esc(a.publisher)}　${esc(a.published_at.slice(0,10))}</div><h2 class="hero-title">${esc(a.title)}</h2><p class="hero-copy">${esc(a.summary)}</p><a class="source" href="${encodeURI(a.sources[0].url)}" target="_blank" rel="noopener noreferrer">查看原始来源</a>`:'<p>当前筛选暂无资讯。</p>';buttons('category-filters',['全部','国际','国内'],'category');buttons('source-filters',['全部',...new Set(state.articles.map(a=>a.publisher))],'source')}
document.addEventListener('click',e=>{if(e.target.matches('[data-key]')){state[e.target.dataset.key]=e.target.dataset.value;render()}});
fetch('data/latest.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{state.articles=d.articles;document.getElementById('updated').textContent=`更新 ${d.updated_at.slice(0,16).replace('T',' ')}`;render()}).catch(()=>{document.getElementById('news-grid').innerHTML='<p>资讯加载失败，请稍后刷新。</p>'});
